from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class DeltaPlanActivationASMV1(SchemaObject):
    cm_plan_id = SchemaField(name="cmPlanId")
    error_message = SchemaField(name="errorMessage")
    id = SchemaField(name="id", not_null=True)
    links = SchemaField(name="links")
    status = SchemaField(name="status", not_null=True)
    procedure_state = SchemaField(name="procedureState")
    operation_id = SchemaField(name="operationId")
    force_reset = SchemaField(name="forceReset")
    auto_lock_cells = SchemaField(name="autoLockCells")
    reset_needed = SchemaField(name="resetNeeded")
    locked_cells = SchemaField(name="lockedCells")

    def __init__(self, cm_plan_id, error_message, id, links, status, procedure_state,
                 operation_id, force_reset, auto_lock_cells, reset_needed, locked_cells):
        self.cm_plan_id = cm_plan_id
        self.error_message = error_message
        self.links = links
        self.id = id
        self.status = status
        self.procedure_state = procedure_state
        self.operation_id = operation_id
        self.force_reset = force_reset
        self.auto_lock_cells = auto_lock_cells
        self.reset_needed = reset_needed
        self.locked_cells = locked_cells

        super(DeltaPlanActivationASMV1, self).__init__()
